insert into products
(slug,name_fr,name_ar,tagline_fr,tagline_ar,description_fr,description_ar,benefits_fr,benefits_ar,ingredients_fr,ingredients_ar,usage_fr,usage_ar,size,price,compare_at_price,disc_2,disc_3,stock,category,sort_order,is_featured)
values
('serum-anti-age','Sérum Anti-Âge','سيروم مضاد للتجاعيد','Le sérum huileux aux 4 huiles précieuses du Maroc','سيروم زيتي بأربعة زيوت مغربية فاخرة','Un sérum nourrissant qui associe l''huile d''argan, l''huile de figue de Barbarie, l''huile de macadamia et l''huile d''amande douce, enrichi en vitamine E. Il aide à lisser le grain de peau, à réduire l''aspect des rides et à redonner de l''éclat et de la souplesse à votre visage.','سيروم مغذٍّ يجمع بين زيت الأركان وزيت التين الشوكي وزيت المقاديميا وزيت اللوز الحلو، مدعّم بفيتامين E. يساعد على تنعيم البشرة وتخفيف مظهر التجاعيد ومنح الوجه نضارة ومرونة.',array['Aide à atténuer l''aspect des rides et ridules','Nourrit en profondeur sans effet gras persistant','Redonne éclat et souplesse à la peau','Formule 100 % naturelle, enrichie en vitamine E']::text[],array['يساعد على تخفيف مظهر التجاعيد والخطوط الدقيقة','يغذي البشرة بعمق دون إحساس بالدهون','يمنح البشرة نضارة ومرونة','تركيبة طبيعية 100% غنية بفيتامين E']::text[],'Huile d''argan, huile de figue de Barbarie, huile de macadamia, huile d''amande douce, vitamine E.','زيت الأركان، زيت التين الشوكي، زيت المقاديميا، زيت اللوز الحلو، فيتامين E.','Le soir, sur peau propre et sèche, déposer 3 à 4 gouttes dans la paume, réchauffer et appliquer par légers massages sur le visage et le cou. À utiliser seul ou sous votre crème.','مساءً على بشرة نظيفة وجافة، ضعي 3 إلى 4 قطرات في راحة اليد، دفّئيها ودلّكي بها الوجه والرقبة بلطف. يستعمل لوحده أو قبل الكريم.','30 ml',249,329,10,15,50,'serum',1,true),
('creme-de-nuit-anti-age','Crème de Nuit Anti-Âge','كريم الليل المضاد للتجاعيد','Hydrate et répare pendant votre sommeil','ترطيب وعناية مكثفة أثناء نومك','Une crème de nuit riche, formulée avec des actifs 100 % naturels : huile d''argan, huile de macadamia et huile de figue de Barbarie. Elle hydrate, nourrit et aide à garder une peau plus jeune et plus lumineuse au réveil.','كريم ليلي غني بمستحضرات طبيعية 100%: زيت الأركان وزيت المقاديميا وزيت التين الشوكي. يرطب ويغذي ويساعد على بشرة أكثر شباباً ونضارة عند الاستيقاظ.',array['Hydratation intense toute la nuit','Aide à prévenir et atténuer les signes de l''âge','Texture riche qui se fond dans la peau','Actifs 100 % naturels']::text[],array['ترطيب مكثف طوال الليل','يساعد على الوقاية من علامات التقدم في السن وتخفيفها','قوام غني يذوب في البشرة','مكونات طبيعية 100%']::text[],'Huile d''argan, huile de macadamia, huile de figue de Barbarie. (Liste INCI complète sur l''emballage.)','زيت الأركان، زيت المقاديميا، زيت التين الشوكي. (القائمة الكاملة للمكونات على العلبة.)','Chaque soir, appliquer une petite quantité sur le visage et le cou propres, masser jusqu''à absorption.','كل مساء، ضعي كمية صغيرة على الوجه والرقبة النظيفين ودلّكي حتى الامتصاص.','',229,299,10,15,50,'creme',2,true),
('masque-eclat-rose','Masque Éclat Rose','ماسك النضارة بالورد','Le masque qui illumine et unifie le teint','ماسك يمنح الإشراقة ويوحّد لون البشرة','Un masque visage à la rose et aux extraits naturels (argan, figue de Barbarie, aloe vera, hamamélis, arnica, thé vert) pour aider à atténuer l''aspect des taches et révéler un teint plus éclatant.','ماسك للوجه بالورد ومستخلصات طبيعية (الأركان، التين الشوكي، الصبار، الهاماميليس، الأرنيكا، الشاي الأخضر) يساعد على تفتيح البشرة وتخفيف مظهر التصبغات.',array['Aide à atténuer l''aspect des taches et du teint terne','Effet bonne mine immédiat','Apaise et hydrate grâce à l''aloe vera','Extraits 100 % naturels']::text[],array['يساعد على تخفيف مظهر التصبغات والبشرة الباهتة','إشراقة فورية على الوجه','يهدئ ويرطب بفضل الصبار','مستخلصات طبيعية 100%']::text[],'Huile d''argan, huile de figue de Barbarie, aloe vera, extrait de rose, hamamélis, arnica, thé vert. (Liste à vérifier avec l''emballage.)','زيت الأركان، زيت التين الشوكي، الصبار، مستخلص الورد، الهاماميليس، الأرنيكا، الشاي الأخضر. (يرجى التحقق من العلبة.)','Appliquer une couche généreuse sur peau propre, laisser poser 10 à 15 minutes puis rincer à l''eau tiède. 2 à 3 fois par semaine.','ضعي طبقة سخية على بشرة نظيفة واتركيها 10 إلى 15 دقيقة ثم اغسليها بماء فاتر. مرتين إلى ثلاث مرات في الأسبوع.','100 ml',149,199,10,15,50,'masque',3,true),
('huile-seche-moukhalat','Huile Sèche Moukhalat','زيت جاف مخلّط','Corps lumineux, parfum envoûtant, hydratation qui dure','جسم لامع، رائحة ساحرة، ترطيب يدوم','Une huile sèche multi-usage à l''huile d''amande douce et à l''huile d''argan, enrichie en vitamine E. Elle nourrit en profondeur, laisse un fini satiné non gras et un parfum qui vous accompagne toute la journée.','زيت جاف متعدد الاستعمالات بزيت اللوز الحلو وزيت الأركان مع فيتامين E. يغذي بعمق ويترك لمسة حريرية غير دهنية ورائحة ترافقك طوال اليوم.',array['Fini sec, non gras, absorption rapide','Nourrit et adoucit la peau du corps','Éclat naturel et parfum qui dure','Huile d''amande douce, argan et vitamine E']::text[],array['قوام جاف غير دهني وامتصاص سريع','يغذي ويطري بشرة الجسم','لمعان طبيعي ورائحة تدوم','زيت اللوز الحلو والأركان وفيتامين E']::text[],'Huile d''amande douce, huile d''argan, vitamine E. (Liste à vérifier avec l''emballage.)','زيت اللوز الحلو، زيت الأركان، فيتامين E. (يرجى التحقق من العلبة.)','Vaporiser sur le corps et les cheveux après la douche ou à tout moment de la journée, et masser légèrement.','رشّي على الجسم والشعر بعد الاستحمام أو في أي وقت من اليوم ودلّكي بلطف.','100 ml',189,249,10,15,50,'huile',4,false),
('gel-gommage-visage','Gel Gommage Visage','جل مقشر للوجه','Exfolie en douceur, hydrate en profondeur','تقشير لطيف وترطيب عميق','Un gel gommant qui associe l''aloe vera, pour une hydratation en profondeur, et des grains de figue de Barbarie qui exfolient la peau en douceur. Résultat : une peau nette, douce et visiblement plus lumineuse.','جل مقشر يجمع بين الصبار لترطيب عميق وحبيبات التين الشوكي التي تقشر البشرة بلطف. النتيجة بشرة نقية وناعمة وأكثر إشراقاً.',array['Élimine les cellules mortes en douceur','Hydrate grâce à l''aloe vera','Peau plus lisse et plus lumineuse','Grains naturels de figue de Barbarie']::text[],array['يزيل الخلايا الميتة بلطف','يرطب بفضل الصبار','بشرة أنعم وأكثر إشراقاً','حبيبات طبيعية من التين الشوكي']::text[],'Aloe vera, grains de figue de Barbarie. (Liste INCI complète sur l''emballage.)','الصبار، حبيبات التين الشوكي. (القائمة الكاملة للمكونات على العلبة.)','Sur visage humide, masser doucement en mouvements circulaires en évitant le contour des yeux, puis rincer. 1 à 2 fois par semaine.','على وجه رطب، دلّكي بحركات دائرية لطيفة مع تجنب محيط العينين ثم اغسلي. مرة إلى مرتين في الأسبوع.','',119,159,10,15,50,'gommage',5,false)
