-- Rosa Alba seed: 5 products with PLACEHOLDER prices (edit them in Admin > Produits)
on conflict (slug) do nothing;

-- Product photos (files live in /public/products)
update products set images = array['/products/' || slug || '-1.jpg'] where slug in ('serum-anti-age','creme-de-nuit-anti-age','masque-eclat-rose','huile-seche-moukhalat','gel-gommage-visage') and (images is null or images = '{}');
